import sqlparse
from sqlparse import sql


def _find_functions(tlist):
    found = []
    for tok in tlist.tokens:
        if isinstance(tok, sql.Function):
            found.append(tok)
        if tok.is_group:
            found.extend(_find_functions(tok))
    return found


def test_lowercase_as_in_create_table_groups_functions():
    stmt = sqlparse.parse('create table foo as select count(*) from bar')[0]
    funcs = _find_functions(stmt)
    names = [f.get_name() for f in funcs]
    assert 'count' in names, names

