import sqlparse
from sqlparse import sql


def _walk(tlist):
    for tok in tlist.tokens:
        yield tok
        if tok.is_group:
            yield from _walk(tok)


def test_mixed_case_as_in_create_table_as_groups_functions():
    stmt = sqlparse.parse('CREATE TABLE t As SELECT max(a) FROM x')[0]
    funcs = [tok for tok in _walk(stmt) if isinstance(tok, sql.Function)]
    assert len(funcs) == 1
    assert funcs[0].get_real_name() == 'max'
